(async function(){
  if(window.CKEDITOR&&CKEDITOR.instances){for(var k in CKEDITOR.instances){if(CKEDITOR.instances[k].updateElement)CKEDITOR.instances[k].updateElement()}}
  var f=document.querySelector("form.write-article");
  var fd=new URLSearchParams();
  f.querySelectorAll("input,textarea,select").forEach(function(e){
    if(!e.name) return;
    if(e.type==="radio"&&!e.checked) return;
    if(e.type==="checkbox") return;
    fd.append(e.name,e.value);
  });
  var resp=await fetch("https://my.oschina.net/u/9762197/blog/publish",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded; charset=UTF-8","X-Requested-With":"XMLHttpRequest"},body:fd.toString(),credentials:"include"});
  var t=await resp.text();
  return resp.status+" | "+t.slice(0,500);
})()
